// DimSupportChannel — generated by src/powerbi/build_assets.py from DimSupportChannel.csv
// Grain/keys: see powerbi/data_model.md
let
    Source   = Csv.Document(File.Contents(DataFolder & "DimSupportChannel.csv"),
                            [Delimiter = ",", Encoding = 65001, QuoteStyle = QuoteStyle.Csv]),
    Promoted = Table.PromoteHeaders(Source, [PromoteAllScalars = true]),
    Typed    = Table.TransformColumnTypes(Promoted, {
        {"channel_key", Int64.Type},
        {"support_channel", type text},
        {"channel_type", type text}
    }, "en-US")
in
    Typed
